USE sakila;

-- 1. List the number of films per category.
SELECT c.name AS "Category", count(f.film_id) AS "Number of Films" FROM sakila.film_category as f
JOIN sakila.category as c
ON f.category_id = c.category_id
GROUP BY c.category_id;

-- 2. Retrieve the store ID, city, and country for each store.
SELECT s.store_id, c.city, ct.country FROM sakila.store as s
JOIN sakila.address as a
ON s.address_id = a.address_id
JOIN sakila.city as c
ON a.city_id = c.city_id
JOIN sakila.country as ct
ON c.country_id = ct.country_id;

-- 3. Calculate the total revenue generated by each store in dollars.
SELECT s.store_id, sum(amount) as "total" FROM payment as p
JOIN staff as st
ON p.staff_id = st.staff_id
JOIN store as s
ON st.store_id = s.store_id
GROUP BY s.store_id;


-- 4. Determine the average running time of films for each category.
SELECT c.name as "Category", ROUND(AVG(f.length),2) as "Length" FROM category as c
JOIN film_category as fc
ON c.category_id = fc.category_id
JOIN film as f
ON fc.film_id = f.film_id
GROUP BY c.name;

